//! Cargo-driven `kernel32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is kernel32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x7c4e0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ffb6000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ffb6000000u64)),
        o => panic!("kernel32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:crate:kernel32-vista-rust::TRUE", "engine:crate:kernel32-shared-rust::TRUE", "engine:wine", "engine:chkstk", "engine:pseh", "import:ntdll", "import:ntdll_vista", "engine:crate:psapi-rust::TRUE", "engine:delayimp_rust", "import:kernel32"],
        "x86_64" => &["body", "engine:crate:kernel32-vista-rust::TRUE", "engine:crate:kernel32-shared-rust::TRUE", "engine:wine", "engine:chkstk", "engine:pseh", "import:ntdll", "import:ntdll_vista", "engine:crate:psapi-rust::TRUE", "engine:delayimp_rust", "import:kernel32"],
        "aarch64" => &["body", "engine:crate:kernel32-vista-rust::TRUE", "engine:crate:kernel32-shared-rust::TRUE", "engine:wine", "engine:chkstk", "engine:pseh", "import:ntdll", "import:ntdll_vista", "engine:crate:psapi-rust::TRUE", "engine:delayimp_rust", "import:kernel32"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/kernel32",
        "dll/win32/kernel32",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/reactos/subsys",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_KERNEL32_", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rust_staticlib("kernel32-rust")
        .c_from_compile_db(
            "kernel32_shims",
            match arch.as_str() {
                "x86" => &["dll/win32/kernel32/client/dep.c", "dll/win32/kernel32/client/i386/fiber.S", "dll/win32/kernel32/client/i386/thread.S"],
                "x86_64" => &["dll/win32/kernel32/client/dep.c", "dll/win32/kernel32/client/amd64/fiber.S"],
                "aarch64" => &["dll/win32/kernel32/client/dep.c", "dll/win32/kernel32/client/arm64/fiber.S"],
                _ => unreachable!(),
            },
        )
        .rc("dll/win32/kernel32/kernel32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/kernel32/kernel32.spec", "kernel32.dll")
        .spec_stubs()
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .delay_import_lib("dll/ntdll/nt_0600/ntdll_vista.spec", "ntdll_vista.dll", "ntdll_vista")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: Some("console:5.01".into()),
        });
}
